import React, { useState } from 'react';
import Modal from '../components/Modal';

export default function SegmentPage() {
  const [showModal, setShowModal] = useState(false);
  const [segments, setSegments] = useState([]); // store saved segments

  // when Modal saves
  const handleSaveSegment = (data) => {
    setSegments(prev => [...prev, data]);
    setShowModal(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-6 bg-gray-50">
      <div className="w-full max-w-4xl bg-white shadow rounded-lg p-8">
        <div className="bg-teal-600 text-white px-6 py-4 rounded mb-6" style={{ backgroundColor: 'var(--teal)' }}>
          <h1 className="text-lg font-semibold">View Audience</h1>
        </div>

        <div className="flex flex-col gap-6">
          {/* Save Segment Button */}
          <div className="h-32 flex items-center justify-center border border-dashed rounded">
            <button
              onClick={() => setShowModal(true)}
              className="px-6 py-3 border border-gray-300 rounded text-gray-700 hover:bg-gray-100"
            >
              Save segment
            </button>
          </div>

          {/* Saved Segments Table */}
          {segments.length > 0 && (
            <div>
              <h2 className="text-lg font-medium mb-3 text-gray-700">Saved Segments</h2>
              <table className="w-full border border-gray-200 text-sm">
                <thead className="bg-gray-100 text-gray-700">
                  <tr>
                    <th className="border p-2 text-left">Segment Name</th>
                    <th className="border p-2 text-left">Schemas</th>
                  </tr>
                </thead>
                <tbody>
                  {segments.map((seg, idx) => (
                    <tr key={idx} className="hover:bg-gray-50">
                      <td className="border p-2">{seg.segment_name}</td>
                      <td className="border p-2">
                        {seg.schema.map((s, i) => (
                          <span key={i} className="inline-block mr-2 bg-[#f9fefe] border border-gray-200 rounded px-2 py-1">
                            {Object.values(s)[0]}
                          </span>
                        ))}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      {showModal && <Modal onClose={() => setShowModal(false)} onSave={handleSaveSegment} />}
    </div>
  );
}
